// Clean-room longest precedence chain of 2-intervals.
#include <algorithm>
#include <array>
#include <cstddef>
#include <cstdint>
namespace { constexpr std::size_t N=16,F=17;bool before(const std::int64_t*v,int a,int b){auto x=1+4*a,y=1+4*b;for(int q=0;q<4;++q)if(v[x+q]!=v[y+q])return v[x+q]<v[y+q];return a<b;}bool precedes(const std::int64_t*v,int a,int b){auto x=1+4*a,y=1+4*b;return v[x+1]<v[y]&&v[x+3]<v[y+2];}template<class A,class B>bool lexless(const A&a,std::size_t an,const B&b,std::size_t bn){for(std::size_t i=0;i<std::min(an,bn);++i)if(a[i]!=b[i])return a[i]<b[i];return an<bn;} }
extern "C" std::int64_t two_interval_precedence_chain(const std::int64_t*v,std::size_t n,std::uint8_t*out,std::size_t cap){if(!v||n<5||n>65||v[0]<1||v[0]>16||n!=1+4*static_cast<std::size_t>(v[0]))return -1;auto count=static_cast<std::size_t>(v[0]);for(std::size_t i=0;i<count;++i){auto p=1+4*i;for(int q=0;q<4;++q)if(v[p+q]<0||v[p+q]>63)return -1;if(v[p]>=v[p+1]||v[p+2]>=v[p+3]||v[p+1]>=v[p+2])return -1;}
 std::array<int,N> order{};for(std::size_t i=0;i<count;++i)order[i]=static_cast<int>(i);std::sort(order.begin(),order.begin()+count,[&](int a,int b){return before(v,a,b);});std::array<std::array<int,N>,N> paths{};std::array<std::size_t,N> len{};for(std::size_t i=0;i<count;++i){paths[i][0]=order[i];len[i]=1;for(std::size_t j=0;j<i;++j)if(precedes(v,order[j],order[i])){auto cand=paths[j];cand[len[j]]=order[i];auto m=len[j]+1;if(m>len[i]||(m==len[i]&&lexless(cand,m,paths[i],len[i]))){paths[i]=cand;len[i]=m;}}}
 std::size_t best=0;for(std::size_t i=1;i<count;++i)if(len[i]>len[best]||(len[i]==len[best]&&lexless(paths[i],len[i],paths[best],len[best])))best=i;std::array<std::int64_t,F> fields{};fields[0]=static_cast<std::int64_t>(len[best]);for(std::size_t i=0;i<len[best];++i)fields[i+1]=paths[best][i];auto bytes=8*(len[best]+1);if(!out||cap<bytes)return -2;for(std::size_t i=0;i<len[best]+1;++i){auto bits=static_cast<std::uint64_t>(fields[i]);for(int b=0;b<8;++b){out[8*i+b]=static_cast<std::uint8_t>(bits);bits>>=8;}}return static_cast<std::int64_t>(bytes);}
